-- What the cases taught, in order. Structural rules are added on one clear case; numbers change only when 3+
-- independent cases agree (calibrate()), per channel, never per mechanism as a whole.
UPDATE case_study SET replay_at = v.t FROM (VALUES (1, TIMESTAMPTZ '2021-03-31'), (2, TIMESTAMPTZ '2024-08-13 06:46-04'),
  (3, TIMESTAMPTZ '2022-10-07 14:30-04'), (5, TIMESTAMPTZ '2019-05-15 18:30-04')) v(id, t) WHERE case_study.id = v.id;
